/** The repositories of fixture-fenced-db, by table. */
export interface FixtureFencedDbRepositories {
  readonly courier: CourierRepository;
  readonly delivery: DeliveryRepository;
  readonly depot: DepotRepository;
  readonly parcel: ParcelRepository;
}

/** The repositories of fixture-fenced-db over a pool, acting as a user or none. */
export type FixtureFencedDbOrm = Orm<FixtureFencedDbRepositories>;

/** The repositories of fixture-fenced-db in a transaction, with its raw SQL. */
export type FixtureFencedDbTx = OrmTx<FixtureFencedDbRepositories>;

/** The tables of fixture-fenced-db and the clauses their statements are written with. */
export const fixtureFencedDbOrm: OrmDefinition = {
  clauses: {
    eq: "%s = $%d",
    ne: "%s IS DISTINCT FROM $%d",
    gt: "%s > $%d",
    gte: "%s >= $%d",
    lt: "%s < $%d",
    lte: "%s <= $%d",
    ilike: "%s ILIKE $%d",
    in: "%s IN (%s)",
    noneOf: "(%s IN (%s)) IS NOT TRUE",
    isNull: "%s IS NULL",
    isNotNull: "%s IS NOT NULL",
    search: "%s ILIKE $%d ESCAPE '\\'",
    exists: "EXISTS (%s)",
    notExists: "NOT EXISTS (%s)",
    set: "%s = $%d",
    setNull: "%s = NULL",
    pageKey: "page_key.%s",
    placeholder: "$%d",
    default: "DEFAULT",
    or: " OR ",
    group: "(%s)",
    where: " WHERE ",
    and: " AND ",
    orderBy: " ORDER BY ",
    orderTerm: "%s %s",
    limit: " LIMIT %d",
    offset: " OFFSET %d",
    setExcluded: "%s = EXCLUDED.%s",
    excluded: "EXCLUDED.%s",
    changed: "(%s) IS DISTINCT FROM (%s)",
    never: "FALSE",
    null: "NULL",
    notIn: "%s NOT IN (%s)",
  },
  defaultLimit: 100,
  manyLimit: 1000000,
  historyActorCTE: "WITH history_actor AS MATERIALIZED (\n\tSELECT set_config('superschematic.history_actor_id', COALESCE($1::text, ''), true) AS _history_actor\n)\n",
  clearHistoryActor: "SELECT set_config('superschematic.history_actor_id', '', true)",
  tables: {
    courier: courierTable,
    delivery: deliveryTable,
    depot: depotTable,
    parcel: parcelTable,
  },
};

/**
 * Opens the repositories of fixture-fenced-db over pool, acting as the user
 * options names, or as the user it is when a string.
 */
export function createOrm(pool: OrmPool, options?: string | null | OrmOptions): FixtureFencedDbOrm {
  return ormOf<FixtureFencedDbRepositories>(pool, fixtureFencedDbOrm, options);
}
